<script setup lang="ts">
/**
 * Two regions on one axis, resized by a draggable or keyboard-stepped divider (`design/components/split-pane.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/split-pane.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import { agentMember } from '@polymorph/vue'
import styles from '@polymorph/recipes/layout/split-pane.module.css'

export type SplitPaneOrientation = NonNullable<SplitPaneProps['orientation']>

export interface SplitPaneProps {
  defaultRatio?: number
  endMin?: number
  /**
   * The separator's accessible name, such as "Resize navigator" rather than "Divider".
   */
  label: string
  /**
   * The axis of the panes; `horizontal` means side by side, as in Stepper.
   */
  orientation?: 'horizontal' | 'vertical'
  /**
   * The start pane's share, 0–1, controlled like Slider's value.
   */
  ratio?: number
  /**
   * Content floors in px, drawn by `minmax()` and respected by the keyboard clamp.
   */
  startMin?: number
}

defineOptions({ name: 'SplitPane', inheritAttrs: false })

const props = withDefaults(defineProps<SplitPaneProps>(), {
  defaultRatio: 0.5,
  endMin: 0,
  orientation: 'horizontal',
  startMin: 0,
})
const emit = defineEmits<{ commit: [ratio: number]; ratioChange: [ratio: number] }>()
defineSlots<{
  end: (props: Record<string, never>) => unknown
  start: (props: Record<string, never>) => unknown
}>()
const uid = useId()
const mirror = ref(Math.min(1, Math.max(0, props.defaultRatio)))
const dragging = ref(false)
const bounds = ref({ min: 0, max: 1 })
const latest = ref(Math.min(1, Math.max(0, props.ratio ?? props.defaultRatio)))
const divider = useTemplateRef<HTMLElement>('divider')
const root = useTemplateRef<HTMLElement>('root')
const horizontal = computed(() => props.orientation === 'horizontal')
const current = computed(() => Math.min(1, Math.max(0, props.ratio ?? mirror.value)))
const clamp = computed(
  () => (value: number) => Math.min(bounds.value.max, Math.max(bounds.value.min, value)),
)
const effective = computed(() => clamp.value(current.value))
const startId = computed(() => `${uid}-start`)
const move = computed(() => (next: number) => {
  const clamped = Math.round(clamp.value(Math.min(1, Math.max(0, next))) * 10000) / 10000
  if (clamped === latest.value) return
  latest.value = clamped
  mirror.value = clamped
  emit('ratioChange', clamped)
})
const measure = computed(() => () => {
  if (root.value === null) return
  const box = root.value.getBoundingClientRect()
  const line = divider.value?.getBoundingClientRect()
  const usable =
    (horizontal.value ? box.width : box.height) -
    (line === undefined ? 0 : horizontal.value ? line.width : line.height)
  if (usable <= 0 || props.startMin + props.endMin >= usable) {
    bounds.value = { min: 0, max: 1 }
    return
  }
  bounds.value = {
    min: Math.min(1, Math.max(0, props.startMin / usable)),
    max: Math.min(1, Math.max(0, 1 - props.endMin / usable)),
  }
})
const pointerDown = computed(() => (event: PointerEvent) => {
  try {
    ;(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId)
  } catch {
    /* an inactive pointer: nothing to capture */
  }
  dragging.value = true
})
const pointerMove = computed(() => (event: PointerEvent) => {
  if (!dragging.value || root.value === null) return
  const box = root.value.getBoundingClientRect()
  const handle = (event.currentTarget as HTMLElement).getBoundingClientRect()
  const thickness = horizontal.value ? handle.width : handle.height
  const usable = (horizontal.value ? box.width : box.height) - thickness
  if (usable <= 0) return
  const rtl = horizontal.value && getComputedStyle(root.value).direction === 'rtl'
  const along = horizontal.value
    ? rtl
      ? box.right - event.clientX
      : event.clientX - box.left
    : event.clientY - box.top
  move.value((along - thickness / 2) / usable)
})
const pointerUp = computed(() => (event: PointerEvent) => {
  if (!dragging.value) return
  const target = event.currentTarget as HTMLElement
  if (target.hasPointerCapture(event.pointerId)) target.releasePointerCapture(event.pointerId)
  dragging.value = false
  emit('commit', latest.value)
})
const keyDown = computed(() => (event: KeyboardEvent) => {
  const rtl =
    horizontal.value && getComputedStyle(event.currentTarget as HTMLElement).direction === 'rtl'
  const grow = horizontal.value ? (rtl ? 'ArrowLeft' : 'ArrowRight') : 'ArrowDown'
  const shrink = horizontal.value ? (rtl ? 'ArrowRight' : 'ArrowLeft') : 'ArrowUp'
  let next: number
  switch (event.key) {
    case grow:
      next = current.value + 0.02
      break
    case shrink:
      next = current.value - 0.02
      break
    case 'PageUp':
      next = current.value + 0.1
      break
    case 'PageDown':
      next = current.value - 0.1
      break
    case 'Home':
      next = bounds.value.min
      break
    case 'End':
      next = bounds.value.max
      break
    default:
      return
  }
  event.preventDefault()
  move.value(next)
  emit('commit', latest.value)
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    measure.value()
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [root.value]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
onMounted(effect1)
watch(() => [props.orientation, props.startMin, props.endMin], effect1, { flush: 'post' })
onBeforeUnmount(() => release1?.())
const effect2 = () => {
  latest.value = current.value
}
watch(() => current.value, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'SplitPane',
    element: () => divider.value,
    state: () => ({ position: Math.round(effective.value * 100) }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            move.value(value / 100)
            emit('commit', latest.value)
          })(),
      },
    },
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <div
    ref="root"
    :class="styles.root"
    :style="{
      '--pm-split-start': `${effective}fr`,
      '--pm-split-end': `${1 - effective}fr`,
      '--pm-split-start-min': `${startMin}px`,
      '--pm-split-end-min': `${endMin}px`,
    }"
    :data-orientation="orientation"
    data-member="split-pane"
  >
    <!-- start -->
    <div :class="styles.pane" :id="startId">
      <slot name="start" />
    </div>
    <!-- divider -->
    <div
      ref="divider"
      :class="styles.divider"
      data-split-pane-part="divider"
      role="separator"
      tabindex="0"
      :aria-label="label"
      :aria-orientation="horizontal ? 'vertical' : 'horizontal'"
      :aria-controls="startId"
      :aria-valuenow="Math.round(effective * 100)"
      :aria-valuemin="Math.round(bounds.min * 100)"
      :aria-valuemax="Math.round(bounds.max * 100)"
      :data-state="dragging ? 'dragging' : undefined"
      @pointerdown="pointerDown($event)"
      @pointermove="pointerMove($event)"
      @pointerup="pointerUp($event)"
      @pointercancel="pointerUp($event)"
      @keydown="keyDown($event)"
    />
    <!-- end -->
    <div :class="styles.pane">
      <slot name="end" />
    </div>
  </div>
</template>
